import{_ as p,a0 as o,w as r,s as d,I as a,x as i,a1 as t,A as n,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"一步步教你如何安裝 Arch Linux | LCTT x X-CMD","titleTemplate":false,"description":"一步步教你如何安裝 Arch Linux | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一步步教你如何安裝 Arch Linux | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一步步教你如何安裝 Arch Linux | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171211 How to Install Arch Linux [Step by Step Guide]","title":"一步步教你如何安裝 Arch Linux","tag":"201712","desc":""},"relativePath":"201712/20171211 How to Install Arch Linux [Step by Step Guide].md","filePath":"[post].md"}'),h={name:"201712/20171211 How to Install Arch Linux [Step by Step Guide].md"};function g(u,s,k,c,b,f){const e=o("Link");return r(),d("div",null,[s[42]||(s[42]=a("h1",{id:"一步步教你如何安裝-arch-linux",tabindex:"-1"},[i("一步步教你如何安裝 Arch Linux "),a("a",{class:"header-anchor",href:"#一步步教你如何安裝-arch-linux","aria-label":"Permalink to “一步步教你如何安裝 Arch Linux”"},"​")],-1)),s[43]||(s[43]=a("p",null,[a("img",{src:"https://itsfoss.com/wp-content/uploads/2017/12/install-arch-linux-featured-800x450.png",alt:"How to install Arch Linux"})],-1)),s[44]||(s[44]=a("blockquote",null,[a("p",null,"簡要説明：這一教程會教你如何用簡單步驟安裝 Arch Linux。")],-1)),a("p",null,[t(e,{href:"https://www.archlinux.org/"},{default:n(()=>[...s[0]||(s[0]=[i("Arch Linux",-1)])]),_:1}),s[2]||(s[2]=i(" 是一個 x86-64 通用發行版，它流行於那些喜歡 ",-1)),t(e,{href:"https://en.wikipedia.org/wiki/Do_it_yourself"},{default:n(()=>[...s[1]||(s[1]=[i("DIY",-1)])]),_:1}),s[3]||(s[3]=i(" Linux 系統的用户和 Linux 鐵桿粉絲當中。其默認的安裝文件只含有一個最基本的系統，它希望使用者自己配置並使用 Arch 系統。其基於 KISS 原則（",-1)),s[4]||(s[4]=a("ruby",null,[i("使它保持簡單、傻瓜"),a("rt",null,"Keep It Simple, Stupid!")],-1)),s[5]||(s[5]=i("），Arch Linux 是一個專注於優雅、代碼正確，精簡而簡潔的系統。",-1))]),a("p",null,[s[7]||(s[7]=i("Arch 支持滾動發佈模式，並且有自己的軟件包管理器 —— ",-1)),t(e,{href:"https://wiki.archlinux.org/index.php/pacman"},{default:n(()=>[...s[6]||(s[6]=[i("pacman",-1)])]),_:1}),s[8]||(s[8]=i("。為了提供一個先鋭的操作系統，Arch 絕不會錯失任何一個最新的源。實際上，它只提供了一個最小化的基本操作系統，使得你可以在低端硬件上安裝 Arch，並且只安裝你所必須的軟件包。",-1))]),s[45]||(s[45]=l('<p>同時，它也是最流行的從頭開始學習 Linux 的操作系統之一。如果你想以 DIY 精神自己體驗一番，你應該嘗試一下 Arch Linux。 這被許多 Linux 用户視作核心的 Linux 體驗。</p><p>在這篇文章裏，我們會了解到如何安裝、配置 Arch 並在其上安裝桌面環境。</p><h3 id="如何安裝-arch-linux" tabindex="-1">如何安裝 Arch Linux <a class="header-anchor" href="#如何安裝-arch-linux" aria-label="Permalink to “如何安裝 Arch Linux”">​</a></h3><p>我們在這裏討論的安裝方法是從你的電腦上<strong>完全刪除已有的操作系統</strong> ，而後在其上安裝 Arch Linux。如果你想遵循這一教程安裝 Arch，請確保你已經備份了所有文件，否則你就會失去它們。切切。</p><p>在你從 USB 上安裝 Arch 之前，請確保你已經滿足了以下條件：</p><h4 id="安裝-arch-linux-的條件" tabindex="-1">安裝 Arch Linux 的條件： <a class="header-anchor" href="#安裝-arch-linux-的條件" aria-label="Permalink to “安裝 Arch Linux 的條件：”">​</a></h4><ul><li>一個兼容 x86_64（例如 64 位）的機器</li><li>最小 512M 內存（建議 2GB）</li><li>最少 1GB 的磁盤空餘空間（日常使用推薦 20GB）</li><li>可以訪問互聯網</li><li>至少有 2GB 存儲空間的 USB 存儲器</li><li>熟悉 Linux 命令列</li></ul><p>一旦你確認滿足所有條件，就可以開始安裝 Arch Linux 了。</p><h4 id="第一步-下載-iso-文件" tabindex="-1">第一步：下載 ISO 文件 <a class="header-anchor" href="#第一步-下載-iso-文件" aria-label="Permalink to “第一步：下載 ISO 文件”">​</a></h4>',9)),a("p",null,[s[10]||(s[10]=i("你可以從",-1)),t(e,{href:"https://www.archlinux.org/download/"},{default:n(()=>[...s[9]||(s[9]=[i("官網",-1)])]),_:1}),s[11]||(s[11]=i("上下載 ISO。安裝 Arch Linux 需要一個至少有 512M 內存和 800M 磁盤空間，併兼容 x86_64 （如 64 位）的機器。不過，建議至少有 2G 內存和 20G 磁盤空間，這樣安裝桌面環境時就不會遇到麻煩。",-1))]),s[46]||(s[46]=a("h4",{id:"第二步-創建一個-arch-linux-的現場版-usb-存儲器",tabindex:"-1"},[i("第二步：創建一個 Arch Linux 的現場版 USB 存儲器 "),a("a",{class:"header-anchor",href:"#第二步-創建一個-arch-linux-的現場版-usb-存儲器","aria-label":"Permalink to “第二步：創建一個 Arch Linux 的現場版 USB 存儲器”"},"​")],-1)),s[47]||(s[47]=a("p",null,[i("我們需要用你剛剛下載的 ISO 文件創建一個 Arch Linux 的"),a("ruby",null,[i("現場版"),a("rt",null,"live")]),i(" USB 存儲器。")],-1)),a("p",null,[s[13]||(s[13]=i("如果你使用 Linux，你可以用 ",-1)),s[14]||(s[14]=a("code",null,"dd",-1)),s[15]||(s[15]=i(" 命令來創建現場版 USB 存儲器。 記得將下面的例子中的 ",-1)),s[16]||(s[16]=a("code",null,"/path/to/archlinux.iso",-1)),s[17]||(s[17]=i(" 改成你的 ISO 文件的實際存儲位置，",-1)),s[18]||(s[18]=a("code",null,"/dev/sdx",-1)),s[19]||(s[19]=i(" 改成你的磁盤設備號（例如 ",-1)),s[20]||(s[20]=a("code",null,"/dev/sdb",-1)),s[21]||(s[21]=i("）。你可以通過 ",-1)),t(e,{href:"https://access.redhat.com/documentation/en-us/red_hat_enterprise_linux/6/html/deployment_guide/s1-sysinfo-filesystems"},{default:n(()=>[...s[12]||(s[12]=[i("lsblk",-1)])]),_:1}),s[22]||(s[22]=i(" 命令來了解你的設備信息。",-1))]),s[48]||(s[48]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dd bs=4M if=/path/to/archlinux.iso of=/dev/sdx status=progress &amp;&amp; sync</span></span></code></pre></div>',1)),a("p",null,[s[24]||(s[24]=i("在 Windows 下，有多種方法來創建現場版 USB 存儲器。 推薦工具是 Rufus。我們之前已經有",-1)),t(e,{href:"https://itsfoss.com/live-usb-antergos/"},{default:n(()=>[...s[23]||(s[23]=[i("如何使用這一工具創建Antergos 現場版 USB 存儲器",-1)])]),_:1}),s[25]||(s[25]=i("的教程。因為 Antergos 發行版是基於 Arc h的，所以你可以使用同一教程。",-1))]),s[49]||(s[49]=l(`<h4 id="步驟三-從現場版-usb-存儲器上啓動" tabindex="-1">步驟三：從現場版 USB 存儲器上啓動 <a class="header-anchor" href="#步驟三-從現場版-usb-存儲器上啓動" aria-label="Permalink to “步驟三：從現場版 USB 存儲器上啓動”">​</a></h4><p>一旦你已經創建了 Arch Linux 的現場版 USB 存儲器，關閉你的電腦。插上你的 USB 存儲器然後啓動系統。在開機啓動時，持續按 F2、F10 或 F1 之類的按鍵（根據你的電腦型號而定）進入啓動設置。在這裏，選擇“從 USB 存儲器或可移除設備啓動”這一項。</p><p>一旦你選擇了它，你會看到這樣一個選項：</p><p><img src="https://itsfoss.com/wp-content/uploads/2017/11/1-2.jpg" alt="Arch Linux"></p><p>選擇“Boot Arch Linux (x86_64)”。經過各種系統檢查後，Arch Linux 會啓動到 root 用户的命令列界面。</p><p>接下來的步驟包括磁盤分區、創建文件系統並掛載它。</p><h4 id="第四步-磁盤分區" tabindex="-1">第四步：磁盤分區 <a class="header-anchor" href="#第四步-磁盤分區" aria-label="Permalink to “第四步：磁盤分區”">​</a></h4><p>第一步就是給你的硬盤分區。單根分區是最簡單的，就在它上面創建根分區（<code>/</code>）分區、交換分區和 <code>home</code> 分區。</p><p>我有一個 19G 的硬盤，我想在這兒安裝 Arch Linux。為了創建分區，輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fdisk /dev/sda</span></span></code></pre></div><p>按 <code>n</code> 創建新分區。按 <code>p</code> 創建主分區，然後選擇分區號。</p><p>第一個扇區會被自動選擇，你只要按回車鍵。在確定分區的最後一個扇區時，請輸入這一分區的大小。</p><p>用相同的方法為 <code>home</code> 和交換分區創建兩個分區，按 <code>w</code> 來保存修改並退出。</p><p><img src="https://itsfoss.com/wp-content/uploads/2017/11/4-root-partition.png" alt="root partition"></p><h4 id="第四步-創建文件系統" tabindex="-1">第四步：創建文件系統 <a class="header-anchor" href="#第四步-創建文件系統" aria-label="Permalink to “第四步：創建文件系統”">​</a></h4><p>因為我們已經有了三個分區，接下來就是創建文件系統來格式化分區。</p><p>我們用 <code>mkfs</code> 命令在根分區和 <code>home</code> 分區上創建文件系統，用 <code>mkswap</code> 創建交換分區。我們用 ext4 文件系統格式化磁盤。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkfs.ext4 /dev/sda1</span></span>
<span class="line"><span>mkfs.ext4 /dev/sda3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>mkswap /dev/sda2</span></span>
<span class="line"><span>swapon /dev/sda2</span></span></code></pre></div><p>將這些分區掛載在根分區和 <code>home</code> 分區下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mount /dev/sda1 /mnt</span></span>
<span class="line"><span>mkdir /mnt/home</span></span>
<span class="line"><span>mount /dev/sda3 /mnt/home</span></span></code></pre></div><h4 id="第五步-安裝" tabindex="-1">第五步：安裝 <a class="header-anchor" href="#第五步-安裝" aria-label="Permalink to “第五步：安裝”">​</a></h4><p>我們已經創建分區並掛載了分區，開始安裝最基本的軟件包。基本的軟件包包括了系統運行所必需的所有軟件包。比如有 GNU BASH shell、文件壓縮工具、文件系統管理工具、C 語言庫、壓縮工具、Linux 內核及其模組，類庫、系統工具、USB 設備工具、Vi 文本編輯器等等。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacstrap /mnt base base-devel</span></span></code></pre></div><h4 id="第六步-配置系統" tabindex="-1">第六步：配置系統 <a class="header-anchor" href="#第六步-配置系統" aria-label="Permalink to “第六步：配置系統”">​</a></h4><p>生成一個 <code>fstab</code> 文件來規定磁盤分區、塊設備，或者遠程文件系統是如何掛載進文件系統中的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>genfstab -U /mnt &gt;&gt; /mnt/etc/fstab</span></span></code></pre></div><p>進入 chroot 環境，這樣可以為當前進程以及子進程切換當前根目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>arch-chroot /mnt</span></span></code></pre></div><p>一些需要與數據總線保持連接的 systemd 工具不能在 chroot 環境下使用，所以需要從當前環境退出。想要退出 chroot，就用下面的命令:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>exit</span></span></code></pre></div><h4 id="第七步-設定時區" tabindex="-1">第七步：設定時區 <a class="header-anchor" href="#第七步-設定時區" aria-label="Permalink to “第七步：設定時區”">​</a></h4><p>用下面這條命令設定時區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ln -sf /usr/share/&lt;時區信息&gt;/&lt;地區&gt;/&lt;城市&gt; /etc/localtime</span></span></code></pre></div><p>獲取時區列表，輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls /usr/share/zoneinfo</span></span></code></pre></div><p>用 <code>hwclock</code> 命令設定硬件時鐘：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>hwclock --systohc --utc</span></span></code></pre></div><h4 id="第八步-設置地區" tabindex="-1">第八步：設置地區 <a class="header-anchor" href="#第八步-設置地區" aria-label="Permalink to “第八步：設置地區”">​</a></h4><p>文件 <code>/etc/locale.gen</code> 在註釋裏包含了所有地區和系統語言設置。用 Vi 打開它，然後去掉你希望選擇語言前面的註釋。 我選擇了 <code>en_GB.UTF-8</code>。</p><p>現在用下面的命令在 <code>/etc</code> 文件夾裏生成 關於地區的配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>locale-gen</span></span>
<span class="line"><span>echo LANG=en_GB.UTF-8 &gt; /etc/locale.conf</span></span>
<span class="line"><span>export LANG=en_GB.UTF-8</span></span></code></pre></div><h4 id="第九步-安裝-bootloader-設置主機名和-root-密碼" tabindex="-1">第九步 ：安裝 bootloader，設置主機名和 root 密碼 <a class="header-anchor" href="#第九步-安裝-bootloader-設置主機名和-root-密碼" aria-label="Permalink to “第九步 ：安裝 bootloader，設置主機名和 root 密碼”">​</a></h4><p>創建 <code>/etc/hostname</code> 文件 然後添加一個對應的主機名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>127.0.1.1 myhostname.localdomain myhostname</span></span></code></pre></div><p>我添加了 <code>ItsFossArch</code> 作為我的主機名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo ItsFossArch &gt; /etc/hostname</span></span></code></pre></div><p>然後也將它添加到 <code>/etc/hosts</code> 中</p><p>為了安裝 bootloader 使用下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -S grub</span></span>
<span class="line"><span>grub-install /dev/sda</span></span>
<span class="line"><span>grub-mkconfig -o /boot/grub/grub.cfg</span></span></code></pre></div><p>創建 root 密碼，輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>passwd</span></span></code></pre></div><p>輸入你想要的密碼。</p><p>完成之後，更新你的系統。但很有可能你的系統已經是最新的，因為你下載的是最新的 ISO。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -Syu</span></span></code></pre></div><p>恭喜! 你已經安裝了 Arch Linux 的命令列版本。</p><p>接下來，我們會了解到如何為 Arch 設置並安裝一個桌面環境。我很喜歡 GNOME 桌面環境，所以在這兒也就選擇了這個。</p><h4 id="第十步-安裝桌面-這一例子中是-gnome" tabindex="-1">第十步：安裝桌面（這一例子中是 GNOME） <a class="header-anchor" href="#第十步-安裝桌面-這一例子中是-gnome" aria-label="Permalink to “第十步：安裝桌面（這一例子中是 GNOME）”">​</a></h4><p>在你安裝桌面之前，你需要先設置網絡。</p><p>你可以用下面的命令看見你的端口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ip link</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2017/12/11.png" alt=""></p><p>在我的電腦上，端口名是 <code>enp0s3</code>。</p><p>將下面這一段加進文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vi /etc/systemd/network/enp0s3.network</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Match]</span></span>
<span class="line"><span>name=en*</span></span>
<span class="line"><span>[Network]</span></span>
<span class="line"><span>DHCP=yes</span></span></code></pre></div><p>保存並退出。重啓網絡來應用你剛才的改動。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl restart systemd-networkd</span></span>
<span class="line"><span>systemctl enable systemd-networkd</span></span></code></pre></div><p>將下面這兩句話加進 <code>/etc/resolv.conf</code> 中</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nameserver 8.8.8.8</span></span>
<span class="line"><span>nameserver 8.8.4.4</span></span></code></pre></div><p>下一步是安裝 X 環境。</p><p>輸入下面的命令安裝 Xorg，並將它作為顯示服務器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -S xorg xorg-server</span></span></code></pre></div><p>gnome 包含了基本的 GNOME桌面，gnome-extra 則包含 GNOME 應用、歸檔管理器、磁盤管理器、文本編輯器和其它的應用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -S gnome gnome-extra</span></span></code></pre></div><p>最後一步是在 Arch 上開啓 GDM 顯示管理器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl start gdm.service</span></span>
<span class="line"><span>systemctl enable gdm.service</span></span></code></pre></div><p>重啓你的系統，你就會看見 GNOME 的登錄界面。</p><h3 id="arch-linux-安裝總結" tabindex="-1">Arch Linux 安裝總結 <a class="header-anchor" href="#arch-linux-安裝總結" aria-label="Permalink to “Arch Linux 安裝總結”">​</a></h3><p>我們在下面的視頻中展示了一個由 Foss 讀者 Gonzalo Tormo 提供的相似的安裝方法（全屏觀看，能更好的看清命令）：</p><p><img src="https://youtu.be/iENmRwVhsTQ" alt="視頻"></p>`,79)),a("p",null,[s[27]||(s[27]=i("你也許意識到安裝 Arch 不像",-1)),t(e,{href:"https://itsfoss.com/install-ubuntu-1404-dual-boot-mode-windows-8-81-uefi/"},{default:n(()=>[...s[26]||(s[26]=[i("安裝 Ubuntu",-1)])]),_:1}),s[28]||(s[28]=i(" 一樣簡單。不過，只要有耐心，你一定可以安裝好它，並且向全世界宣佈你在用 Arch Linux。",-1))]),s[50]||(s[50]=a("p",null,"Arch Linux 安裝過程本身就是一個學習的機會。一旦安裝完畢，我建議你參考它的 Wiki 去嘗試其它的桌面環境，從而更深入瞭解這一操作系統。你可以探索它，發現它的強大之處。",-1)),s[51]||(s[51]=a("p",null,"如果你在安裝 Arch 的過程中遇到任何問題，請在評論中給我們留言。",-1)),s[52]||(s[52]=a("hr",null,null,-1)),a("p",null,[s[30]||(s[30]=i("via: ",-1)),t(e,{href:"https://itsfoss.com/install-arch-linux/"},{default:n(()=>[...s[29]||(s[29]=[i("https://itsfoss.com/install-arch-linux/",-1)])]),_:1})]),a("p",null,[s[34]||(s[34]=i("作者：",-1)),t(e,{href:"https://itsfoss.com/author/ambarish/"},{default:n(()=>[...s[31]||(s[31]=[i("Ambarish Kumar",-1)])]),_:1}),s[35]||(s[35]=i(" 譯者：",-1)),t(e,{href:"https://github.com/wenwensnow"},{default:n(()=>[...s[32]||(s[32]=[i("wenwensnow",-1)])]),_:1}),s[36]||(s[36]=i(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[33]||(s[33]=[i("wxy",-1)])]),_:1})]),a("p",null,[s[39]||(s[39]=i("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[37]||(s[37]=[i("LCTT",-1)])]),_:1}),s[40]||(s[40]=i(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:n(()=>[...s[38]||(s[38]=[i("Linux中國",-1)])]),_:1}),s[41]||(s[41]=i(" 榮譽推出",-1))])])}const v=p(h,[["render",g]]);export{y as __pageData,v as default};
